        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int mode = (int) in.nval;
        int[] color = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            color[i] = (int) in.nval;
        }
        int[][] edges = new int[Math.max(0, n - 1)][2];
        for (int i = 0; i < n - 1; i++) {
            in.nextToken();
            edges[i][0] = (int) in.nval;
            in.nextToken();
